import{z as d,x as A,o as E,c as s,q as o,j as l,D as a,d as n,s as i,S as r}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"嵌入模型的池化","description":"","frontmatter":{"title":"嵌入模型的池化","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/embedding-pooling.md","filePath":"llm/embedding-pooling.md","lastUpdated":1791063341000}'),B={name:"llm/embedding-pooling.md"};function p(m,e,c,h,_,C){const t=A("Mermaid");return E(),s("div",null,[e[2]||(e[2]=o('<h1 id="嵌入模型的池化" tabindex="-1">嵌入模型的池化 <a class="header-anchor" href="#嵌入模型的池化" aria-label="Permalink to &quot;嵌入模型的池化&quot;">​</a></h1><div class="epigraph"><p>用孪生双向编码器分别编码句对，并以均值池化得到句向量，比拿 CLS 向量做余弦更适合语义检索。</p><footer>—— Reimers &amp; Gurevych, Sentence-BERT, EMNLP 2019</footer></div><p><a href="/llm/bidirectional-prefix-mask">上一课</a>让单栈也能给前缀双向表示，但输出仍是变长的隐状态序列。检索、聚类、路由要把一条文本收成固定维向量。本课补池化：在双向（或前缀）编码器的最后一层上，如何把 \\(m\\) 个位置合成一个 \\(d\\) 维句向量。单元到此结束；下一单元改注意力内部的门与共享，不再把编码器当主对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/bert-encoder">BERT 编码器</a>把 <code>[CLS]</code> 训成分类查询，NSP 与句对分类会用它。直接拿 <code>[CLS]</code> 做余弦相似度，Reimers 与 Gurevych 观察到排序很弱：那个位置优化的是分类间隔，不是度量空间里的语义距离。缺口是：<strong>句向量的训练目标与池化算子必须一起选</strong>，不能假定编码器最后一层的某个特殊 token 已经是嵌入。</p><p>纯解码器末 token 或均值也可以凑句向量，但因果掩码让靠前的 token 从未看见全句，池化平均的是一串不对称的前缀表示。双向或前缀全可见，是池化有意义的前提。</p><p><span class="marginnote">本课的嵌入是语义向量，不是输入层的 token embedding，也不是量化课里的权重量化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记最后一层隐状态 \\(H\\in\\mathbb{R}^{m\\times d}\\)，有效位置集合 \\(\\mathcal{I}\\)（去掉 padding、常去掉 <code>[CLS]</code>/<code>[SEP]</code>）。均值池化</p> \\[z=\\frac{1}{|\\mathcal{I}|}\\sum_{i\\in\\mathcal{I}} h_i, \\]<p>可选再乘一个线性 \\(W\\) 降到嵌入维。最大池化取各维最大值，对短句噪声敏感。<code>[CLS]</code> 池化即 \\(z=h_{\\mathrm{CLS}}\\)。加权均值用注意力或 IDF 当权。对比学习（NLI 句对、检索正负例）的损失加在 \\(z\\) 的余弦或温度缩放点积上，反向传到整段双向栈。</p><p>Sentence-BERT 的默认实践：孪生双塔，两句独立过同一编码器，均值池化，用分类或回归头训 NLI；推理只保留编码器与池化，句向量可缓存。后课若说「嵌入模型」，默认是这种双塔加池化，不是交叉编码器逐对打分。</p><p><span class="marginnote">数字实例：一条 768 维 FP32 句向量约 \\(768\\times4\\) 字节 \\(=3\\) KB。一亿篇文档就是约 300 GB——双塔「可缓存」的价值在这里兑现：向量离线算一次反复用，查询侧每条只需一次编码加一次点积。</span></p>',13)),(E(),l(r,null,{default:a(()=>[i(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20T1%5B%22%E5%A1%94%E4%B8%80%3A%20%E7%BC%96%E7%A0%81%20%2B%20%E6%B1%A0%E5%8C%96%20(%E5%9C%A8%E7%BA%BF)%22%5D%0A%20%20D%5B%22%E6%96%87%E6%A1%A3%22%5D%20--%3E%20T2%5B%22%E5%A1%94%E4%BA%8C%3A%20%E7%BC%96%E7%A0%81%20%2B%20%E6%B1%A0%E5%8C%96%20(%E5%8F%AF%E7%A6%BB%E7%BA%BF%E7%BC%93%E5%AD%98)%22%5D%0A%20%20T1%20--%3E%20DOT%5B%22%E5%90%91%E9%87%8F%E7%82%B9%E7%A7%AF%E6%89%93%E5%88%86%22%5D%0A%20%20T2%20--%3E%20DOT%0A%20%20Q%20--%3E%20X%5B%22%E4%BA%A4%E5%8F%89%E7%BC%96%E7%A0%81%E5%99%A8%3A%20%E6%9F%A5%E8%AF%A2%E4%B8%8E%E6%96%87%E6%A1%A3%E6%8B%BC%E6%88%90%E4%B8%80%E5%AF%B9%22%5D%0A%20%20D%20--%3E%20X%0A%20%20X%20--%3E%20SCORE%5B%22%E5%8F%8C%E5%90%91%E6%B3%A8%E6%84%8F%E5%8A%9B%E7%9B%B4%E6%8E%A5%E6%89%93%E7%9B%B8%E5%85%B3%E5%88%86%22%5D%0A%20%20DOT%20--%3E%20P%5B%22%E5%85%88%E6%A3%80%E7%B4%A2%3A%20%E7%B2%97%E6%8E%92%E5%87%BA%E5%80%99%E9%80%89%22%5D%0A%20%20SCORE%20--%3E%20P2%5B%22%E5%86%8D%E9%87%8D%E6%8E%92%3A%20%E5%AF%B9%E5%80%99%E9%80%89%E7%B2%BE%E6%8E%92%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<h3 id="双塔与交叉编码器" tabindex="-1">双塔与交叉编码器 <a class="header-anchor" href="#双塔与交叉编码器" aria-label="Permalink to &quot;双塔与交叉编码器&quot;">​</a></h3><p>交叉编码器把两句拼成一对，用双向注意力直接打相关分，准但不可预计算。池化嵌入把交互推迟到向量点积，准度通常略低，规模上可以先检索再交叉重排。本课只钉死池化这一侧。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>均值把每个位置当成一次对句向量的投票，梯度均匀回传到可见 token，迫使各位置都携带可加的语义，而不是把信息堆进 <code>[CLS]</code>。对比损失再把同一语义的 \\(z\\) 拉近、不同的推远，池化后的空间才有余弦意义。若仍用 MLM 损失而不加对比，均值向量常常塌成各向近乎同质的表示，检索崩溃。</p><p>长度归一化 \\(1/|\\mathcal{I}|\\) 避免长文档仅仅因为项多而范数膨胀。有的配方再对 \\(z\\) 做 \\(\\ell_2\\) 归一化，让下游只剩角度。</p><p><span class="marginnote">术语翻译：\\(\\ell_2\\) 归一化就是把向量除以自己的长度，让所有句子向量都躺在半径为 1 的球面上。此后余弦相似度退化成普通点积，检索系统可以直接用内积索引（如 HNSW），不必再单独算夹角。</span></p><p><span class="marginnote">指令式嵌入会在前缀放「把下面的文档编成检索向量」一类提示。池化仍发生在提示加文档的双向段上；提示是条件，不是第二个句子的交叉注意力。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>池化丢掉词序与对齐，否定、数量、细粒度论元容易糊。需要字面匹配或重排时，应回到 token 级交叉注意力，而不是把均值向量做得更宽。因果解码器当嵌入模型，必须改掩码或只池化能看见全句的位置，否则前半句表示系统性偏弱。<code>[CLS]</code> 在分类微调后可以很好，迁移到检索仍应重训池化目标。</p><p><span class="marginnote">常见误区：初学者容易以为向量检索「读懂了」句子；实际上均值把词序冲淡后，「所有鸟都会飞」与「不是所有鸟都会飞」的向量可能非常接近。凡是答案依赖否定、数字或精确匹配的场景，都要靠重排或交叉编码器兜底。</span></p>',10)),(E(),l(r,null,{default:a(()=>[i(t,{id:"mermaid-66",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%96%87%E6%9C%AC%22%5D%20--%3E%20ENC%5B%22%E5%8F%8C%E5%90%91%E6%88%96%E5%89%8D%E7%BC%80%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20ENC%20--%3E%20H%5B%22%E4%BD%8D%E7%BD%AE%E8%A1%A8%E7%A4%BA%22%5D%0A%20%20H%20--%3E%20Pool%5B%22%E5%9D%87%E5%80%BC%20%2F%20CLS%20%2F%20%E5%8A%A0%E6%9D%83%22%5D%0A%20%20Pool%20--%3E%20Z%5B%22%E5%8F%A5%E5%90%91%E9%87%8F%20z%22%5D%0A%20%20Z%20--%3E%20Cos%5B%22%E4%BD%99%E5%BC%A6%E6%A3%80%E7%B4%A2%E6%88%96%E5%AF%B9%E6%AF%94%E6%8D%9F%E5%A4%B1%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>句向量需要池化算子加度量目标；BERT 的 <code>[CLS]</code> 不是检索默认。</li><li>均值池化在全可见掩码上把各位置收成可加语义，对比学习赋予余弦意义。</li><li>双塔可缓存，交叉编码器更准但不可预计算；二者不要混成同一种「嵌入」。</li><li>因果栈未经掩码改造就均值，会平均一串不完整的前缀表示。</li><li>出处：Reimers &amp; Gurevych, <em>Sentence-BERT</em>, EMNLP 2019。</li></ul>',2))])}const S=d(B,[["render",p]]);export{T as __pageData,S as default};
